import * as React from "react"
import { Link } from "gatsby"
import Header from "../components/Header"
import Seo from "../components/Seo"
import { ArrowRight } from "../components/Icons"
import GeneratedSite from "../components/builder/GeneratedSite"
import { load } from "../lib/site-content"
import * as s from "../components/NotFound.module.css"

/**
 * The catch-all 404 — MTC-FCS-045.
 * ============================================================================
 * GitHub Pages serves its own "File not found" page for an unknown path, with
 * the GitHub logo and a link to their documentation on it. That tells every
 * visitor — and every competitor — exactly what this site is hosted on.
 *
 * Gatsby builds this page to `public/404.html`, which is the file Pages looks
 * for and serves in place of its own. The production build validates this
 * output before publishing; source changes require a live deployment before
 * GitHub Pages can serve them (see README.md).
 *
 * ── IT IS A WAY BACK, NOT AN APOLOGY ───────────────────────────────────────
 * Somebody landing here mistyped an address or followed an old link. The
 * useful thing is the three places they were probably going, not a paragraph
 * about what a 404 is.
 */

const PLACES = [
  { to: "/website-builder", label: "Build a free website", note: "Two minutes, no account." },
  { to: "/invoice-builder", label: "Make an invoice", note: "Free, prints to PDF." },
  { to: "/qr-codes", label: "Make a QR code", note: "For your van, or a flyer." },
]

/* ── A PAGE AT freecontractorservices.com/{name} — FCS-114 ─────────────────
   The host serves this file for any address it has no page for, so a name that
   is not one of ours lands here. If an administrator has made a test page under
   that name (admin → Settings → Test addresses) it is drawn instead of the 404.
   Nothing else is affected: an address with no test page behind it still gets the
   404 it always did, after one small check that fails quietly. */
const pathName = () => {
  if (typeof window === "undefined") return ""
  const name = window.location.pathname.replace(/^\/+|\/+$/g, "")
  return /^[a-z0-9]+(-[a-z0-9]+)*$/.test(name) && name.length <= 50 ? name : ""
}

const NotFoundPage = () => {
  const [lookup, setLookup] = React.useState({ state: "idle" }) // idle | checking | found | none

  React.useEffect(() => {
    const name = pathName()
    if (!name) return undefined
    let alive = true
    setLookup({ state: "checking" })
    load(`path--${name}`).then(result => {
      if (alive) setLookup(result.ok ? { state: "found", site: result.site } : { state: "none" })
    })
    return () => {
      alive = false
    }
  }, [])

  /* While it checks, the ordinary 404 stays on screen. Swapping in a spinner of a
     different height made every wrong address jump up and down on load (FCS-115); the
     one case that does change — an administrator's test page — changes once, when found. */
  if (lookup.state === "found") {
    /* It is THEIR page, so none of our chrome around it: the page shell adds our footer to every route, and
       a customer on a subdomain does not get it either (FCS-057). Hidden only while their page is shown. */
    return (
      <>
        <style>{".site-shell > footer { display: none }"}</style>
        <GeneratedSite draft={lookup.site.content} plan={lookup.site.plan} mode="remote" />
      </>
    )
  }
  return <NotFound />
}

const NotFound = () => (
  <>
    <Header />
    <main className={s.page}>
      <div className="container">
        <p className={s.code}>404</p>
        <h1 className={s.title}>That page is not here</h1>
        <p className={s.lead}>
          The address may have changed, or it may have been mistyped. Nothing is broken — here is
          where most people are going.
        </p>

        <div className={s.cards}>
          {PLACES.map(place => (
            <Link key={place.to} to={place.to} className={s.card}>
              <span className={s.cardTitle}>{place.label}</span>
              <span className={s.cardNote}>{place.note}</span>
              <ArrowRight className={s.cardArrow} />
            </Link>
          ))}
        </div>

        <p className={s.tail}>
          Looking for a contractor&rsquo;s website we host? Check the address — they usually look
          like <span className={s.mono}>name.freecontractorservices.com</span>.{" "}
          <Link to="/">Back to the home page</Link>.
        </p>
      </div>
    </main>
  </>
)

export const Head = () => (
  <Seo title="Page not found" description="That page is not here." noindex />
)

export default NotFoundPage
